package day3;

public class StringToInt {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
    // String to Int
		
		String str = "400";
		
		System.out.println("String value is :" +str);
		
		int num = Integer.parseInt(str);
		
		System.out.println("New integer value is : " + num);
		
	}

}
